window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b6311a0dcd8aaba4"]={"versions": [{"id": "FIG-b6311a0dcd8aaba4", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P06Check</code> innerhalb des End-to-End-Kommunikationsschutzes (E2E-Protokoll, Profile 6). Das Diagramm modelliert die algorithmische Ablauflogik zur Eingangsvalidierung, Extraktion der Protokollfelder (Länge, Counter, CRC) sowie Durchführung der Datenintegritäts- und Plausibilitätsprüfungen auf Empfängerseite.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Einstiegspunkt: Startknoten (Initial Node) der C-Funktion <code>E2E_P06Check(Config, State, Data, Length)</code>.</li>\n<li>Parameter:</li>\n<li><code>Config</code>: Konfigurationsstruktur des Profils 6 (<code>E2E_P06ConfigType</code>).</li>\n<li><code>State</code>: Zustandsstruktur der Empfängerinstanz (<code>E2E_P06CheckStateType</code>).</li>\n<li><code>Data</code>: Zeiger auf den empfangenen Datenpuffer (<code>uint8*</code>).</li>\n<li><code>Length</code>: Länge des empfangenen Puffers in Byte (<code>uint16</code>).</li>\n<li>Unteraktivitäten / Aktionsknoten:</li>\n<li><code>Verify inputs of the check function</code>: Validierung der Eingabeparameter.</li>\n<li><code>Compute offset</code>: Berechnung des feldbezogenen Byte-Offsets im Datenstrom.</li>\n<li><code>Read Length</code>: Einlesen des übertragenen Längenfeldes aus dem Datenstrom.</li>\n<li><code>Read Counter</code>: Auslesen des Sequenzzählers aus dem Header.</li>\n<li><code>Read CRC</code>: Auslesen des übertragenen Prüfwerts.</li>\n<li><code>Compute CRC</code>: Berechnung der E2E-Profil-6-Prüfsumme über Nutzdaten und Daten-ID.</li>\n<li><code>Do checks</code>: Abgleich von CRC, Zählerfolge und Statusfortschreibung.</li>\n<li>Verzweigungsknoten (Decision Node): Prüfung der Bedingung <code>NewDataAvailable == TRUE</code>.</li>\n<li>Ablaufendknoten (Activity Final Nodes) mit Rückgabewerten (<code>Std_ReturnType</code>):</li>\n<li><code>return E2E_E_INPUTERR_NULL</code>: Beendigung bei unzulässigen Null-Zeigern.</li>\n<li><code>return E2E_E_INPUTERR_WRONG</code>: Beendigung bei ungültigen Parameterwerten / Konfigurationsgrenzen.</li>\n<li><code>return E2E_E_OK</code>: Erfolgreicher Durchlauf der Prüfroutine.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Aufruf von <code>E2E_P06Check</code> und Übergang in <code>Verify inputs of the check function</code>.</li>\n<li>Validierung der Eingabeparameter:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei fehlerhafter Zeigerreferenz führt ein Zweig direkt zum Endknoten <code>return E2E_E_INPUTERR_NULL</code>.</li>\n<li>Bei ungültigen Werten (Guard <code>[wrong input]</code>) führt der rechte Zweig direkt zum Endknoten <code>return E2E_E_INPUTERR_WRONG</code>.</li>\n<li>Bei gültigen Eingaben (Guard <code>[input ok]</code>) führt der Pfad zum Verzweigungsknoten <code>NewDataAvailable == TRUE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Verzweigung nach Datenverfügbarkeit:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Sequenzielle Ausführung von <code>Compute offset</code> -> <code>Read Length</code> -> <code>Read Counter</code> -> <code>Read CRC</code> -> <code>Compute CRC</code> -> <code>Do checks</code>.</li>\n<li><code>[FALSE]</code>: Umgehung der Extraktions- und CRC-Berechnungsschritte unter direktem Übergang zu <code>Do checks</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach Abschluss von <code>Do checks</code> Beendigung der Funktion über den regulären Endknoten <code>return E2E_E_OK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Kontrollfluss-Spezifikation für die Implementierung der Funktion <code>E2E_P06Check</code> gemäß Anforderung <code>[PRS_E2E_00430]</code>. Die Fehlerbehandlung unterscheidet strikt zwischen Null-Pointer-Verletzungen (<code>E2E_E_INPUTERR_NULL</code>) und Wertebereichsverletzungen (<code>E2E_E_INPUTERR_WRONG</code>), bevor Datenoperationen ausgeführt werden. Wenn keine neuen Daten bereitstehen (<code>NewDataAvailable == FALSE</code>), dürfen keine Lese- oder Rechenoperationen auf dem Datenpuffer stattfinden; stattdessen ist direkt die Zustandsauswertung in <code>Do checks</code> zu durchlaufen.</p>"}, {"id": "FIG-712c4d308af0d3f5", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P06Check</code> innerhalb des End-to-End-Kommunikationsschutzes (E2E-Protokoll, Profile 6). Das Diagramm modelliert die algorithmische Ablauflogik zur Eingangsvalidierung, Extraktion der Protokollfelder (Länge, Counter, CRC) sowie Durchführung der Datenintegritäts- und Plausibilitätsprüfungen auf Empfängerseite.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Einstiegspunkt: Startknoten (Initial Node) der C-Funktion <code>E2E_P06Check(Config, State, Data, Length)</code>.</li>\n<li>Parameter:</li>\n<li><code>Config</code>: Konfigurationsstruktur des Profils 6 (<code>E2E_P06ConfigType</code>).</li>\n<li><code>State</code>: Zustandsstruktur der Empfängerinstanz (<code>E2E_P06CheckStateType</code>).</li>\n<li><code>Data</code>: Zeiger auf den empfangenen Datenpuffer (<code>uint8*</code>).</li>\n<li><code>Length</code>: Länge des empfangenen Puffers in Byte (<code>uint16</code>).</li>\n<li>Unteraktivitäten / Aktionsknoten:</li>\n<li><code>Verify inputs of the check function</code>: Validierung der Eingabeparameter.</li>\n<li><code>Compute offset</code>: Berechnung des feldbezogenen Byte-Offsets im Datenstrom.</li>\n<li><code>Read Length</code>: Einlesen des übertragenen Längenfeldes aus dem Datenstrom.</li>\n<li><code>Read Counter</code>: Auslesen des Sequenzzählers aus dem Header.</li>\n<li><code>Read CRC</code>: Auslesen des übertragenen Prüfwerts.</li>\n<li><code>Compute CRC</code>: Berechnung der E2E-Profil-6-Prüfsumme über Nutzdaten und Daten-ID.</li>\n<li><code>Do checks</code>: Abgleich von CRC, Zählerfolge und Statusfortschreibung.</li>\n<li>Verzweigungsknoten (Decision Node): Prüfung der Bedingung <code>NewDataAvailable == TRUE</code>.</li>\n<li>Ablaufendknoten (Activity Final Nodes) mit Rückgabewerten (<code>Std_ReturnType</code>):</li>\n<li><code>return E2E_E_INPUTERR_NULL</code>: Beendigung bei unzulässigen Null-Zeigern.</li>\n<li><code>return E2E_E_INPUTERR_WRONG</code>: Beendigung bei ungültigen Parameterwerten / Konfigurationsgrenzen.</li>\n<li><code>return E2E_E_OK</code>: Erfolgreicher Durchlauf der Prüfroutine.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Aufruf von <code>E2E_P06Check</code> und Übergang in <code>Verify inputs of the check function</code>.</li>\n<li>Validierung der Eingabeparameter:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei fehlerhafter Zeigerreferenz (Guard <code>[null input]</code>) führt der linke Pfad zum Endknoten <code>return E2E_E_INPUTERR_NULL</code>.</li>\n<li>Bei ungültigen Werten (Guard <code>[wrong input]</code>) führt der rechte Pfad zum Endknoten <code>return E2E_E_INPUTERR_WRONG</code>.</li>\n<li>Bei gültigen Eingaben (Guard <code>[input ok]</code>) führt der Pfad zum Verzweigungsknoten <code>NewDataAvailable == TRUE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Verzweigung nach Datenverfügbarkeit:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Sequenzielle Ausführung von <code>Compute offset</code> -> <code>Read Length</code> -> <code>Read Counter</code> -> <code>Read CRC</code> -> <code>Compute CRC</code> -> <code>Do checks</code>.</li>\n<li><code>[FALSE]</code>: Umgehung der Extraktions- und CRC-Berechnungsschritte unter direktem Übergang zu <code>Do checks</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach Abschluss von <code>Do checks</code> Beendigung der Funktion über den regulären Endknoten <code>return E2E_E_OK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Kontrollfluss-Spezifikation für die Implementierung der Funktion <code>E2E_P06Check</code> gemäß Anforderung <code>[PRS_E2E_00430]</code>. Die Fehlerbehandlung unterscheidet strikt zwischen Null-Pointer-Verletzungen (<code>E2E_E_INPUTERR_NULL</code>) und Wertebereichsverletzungen (<code>E2E_E_INPUTERR_WRONG</code>), bevor Datenoperationen ausgeführt werden. Wenn keine neuen Daten bereitstehen (<code>NewDataAvailable == FALSE</code>), dürfen keine Lese- oder Rechenoperationen auf dem Datenpuffer stattfinden; stattdessen ist direkt die Zustandsauswertung in <code>Do checks</code> zu durchlaufen.</p>"}, {"id": "FIG-cef24035c5a8bc10", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P06Check</code> innerhalb des End-to-End-Kommunikationsschutzes (E2E-Protokoll, Profile 6). Das Diagramm modelliert die algorithmische Ablauflogik zur Eingangsvalidierung, Extraktion der Protokollfelder (Länge, Counter, CRC) sowie Durchführung der Datenintegritäts- und Plausibilitätsprüfungen auf Empfängerseite.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Einstiegspunkt: Startknoten (Initial Node) der C-Funktion <code>E2E_P06Check(Config, State, Data, Length)</code>.</li>\n<li>Parameter:</li>\n<li><code>Config</code>: Konfigurationsstruktur des Profils 6 (<code>E2E_P06ConfigType</code>).</li>\n<li><code>State</code>: Zustandsstruktur der Empfängerinstanz (<code>E2E_P06CheckStateType</code>).</li>\n<li><code>Data</code>: Zeiger auf den empfangenen Datenpuffer (<code>uint8*</code>).</li>\n<li><code>Length</code>: Länge des empfangenen Puffers in Byte (<code>uint16</code>).</li>\n<li>Unteraktivitäten / Aktionsknoten:</li>\n<li><code>Verify inputs of the check function</code>: Validierung der Eingabeparameter.</li>\n<li><code>Compute offset</code>: Berechnung des feldbezogenen Byte-Offsets im Datenstrom.</li>\n<li><code>Read Length</code>: Einlesen des übertragenen Längenfeldes aus dem Datenstrom.</li>\n<li><code>Read Counter</code>: Auslesen des Sequenzzählers aus dem Header.</li>\n<li><code>Read CRC</code>: Auslesen des übertragenen Prüfwerts.</li>\n<li><code>Compute CRC</code>: Berechnung der E2E-Profil-6-Prüfsumme über Nutzdaten und Daten-ID.</li>\n<li><code>Do checks</code>: Abgleich von CRC, Zählerfolge und Statusfortschreibung.</li>\n<li>Verzweigungsknoten (Decision Node): Prüfung der Bedingung <code>NewDataAvailable == TRUE</code>.</li>\n<li>Ablaufendknoten (Activity Final Nodes) mit Rückgabewerten (<code>Std_ReturnType</code>):</li>\n<li><code>return E2E_E_INPUTERR_NULL</code>: Beendigung bei unzulässigen Null-Zeigern.</li>\n<li><code>return E2E_E_INPUTERR_WRONG</code>: Beendigung bei ungültigen Parameterwerten / Konfigurationsgrenzen.</li>\n<li><code>return E2E_E_OK</code>: Erfolgreicher Durchlauf der Prüfroutine.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Aufruf von <code>E2E_P06Check</code> und Übergang in <code>Verify inputs of the check function</code>.</li>\n<li>Validierung der Eingabeparameter:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei fehlerhafter Zeigerreferenz (Guard <code>[null input]</code>) führt der linke Pfad zum Endknoten <code>return E2E_E_INPUTERR_NULL</code>.</li>\n<li>Bei ungültigen Werten (Guard <code>[wrong input]</code>) führt der rechte Pfad zum Endknoten <code>return E2E_E_INPUTERR_WRONG</code>.</li>\n<li>Bei gültigen Eingaben (Guard <code>[input ok]</code>) führt der Pfad zum Verzweigungsknoten <code>NewDataAvailable == TRUE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Verzweigung nach Datenverfügbarkeit:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Sequenzielle Ausführung von <code>Compute offset</code> -> <code>Read Length</code> -> <code>Read Counter</code> -> <code>Read CRC</code> -> <code>Compute CRC</code> -> <code>Do checks</code>.</li>\n<li><code>[FALSE]</code>: Umgehung der Extraktions- und CRC-Berechnungsschritte unter direktem Übergang zu <code>Do checks</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach Abschluss von <code>Do checks</code> Beendigung der Funktion über den regulären Endknoten <code>return E2E_E_OK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Kontrollfluss-Spezifikation für die Implementierung der Funktion <code>E2E_P06Check</code> gemäß Anforderung <code>[PRS_E2E_00430]</code>. Die Fehlerbehandlung unterscheidet strikt zwischen Null-Pointer-Verletzungen (<code>E2E_E_INPUTERR_NULL</code>) und Wertebereichsverletzungen (<code>E2E_E_INPUTERR_WRONG</code>), bevor Datenoperationen ausgeführt werden. Wenn keine neuen Daten bereitstehen (<code>NewDataAvailable == FALSE</code>), dürfen keine Lese- oder Rechenoperationen auf dem Datenpuffer stattfinden; stattdessen ist direkt die Zustandsauswertung in <code>Do checks</code> zu durchlaufen.</p>"}], "trans": [{"from": "FIG-b6311a0dcd8aaba4", "to": "FIG-712c4d308af0d3f5", "fr": "R19-03", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Kante von Unteraktivität <code>Verify inputs of the check function</code> zum Endknoten <code>return E2E_E_INPUTERR_NULL</code>: Guard <code>[null input]</code> als Beschriftung ergänzt.</li>\n<li>Kantenbeschriftung <code>[wrong input]</code> vom rechten Kontrollfluss vertikal nach oben direkt neben die ausgehende Kante von <code>Verify inputs of the check function</code> verschoben.</li>\n<li>Kantenbeschriftung <code>[input ok]</code> zweizeilig gesetzt (<code>[input</code> / <code>ok]</code>).</li>\n</ul>"}, {"from": "FIG-712c4d308af0d3f5", "to": "FIG-cef24035c5a8bc10", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
